using RailwayWebBuilderCore.Enums;

namespace RailwayWebBuilderCore._SiteData.ModelRailways.Layouts;

internal class ProvidenceColliery : LayoutBase
{
    public ProvidenceColliery()
    {
        Name = LayoutNamesEnums.ProvidenceColliery;
        Owner = "Theo Thomas and friends";
        Description = "Coal has been mined in the West Gloucester area known as the Forest of Dean since before Roman times - by 1787 there were 121 small mines in the Forest, and by 1841 over 145,000 tonnes of coal was produced annually, but water ingress and flooding was always a severe problem and the last big collieries such as Northern United closed in 1965. Providence Colliery is based on several Forest of Dean collieries in the late 1950s and represents a drift mine, as most of the 'gales', or coal measures, follow a shallow slope into the hillsides. Full coal tubs can be seen emerging from the mine entrance tunnel before the coal is unloaded into standard gauge British Railways (WR) wagons marshalled below the screens building. The layout is 16.5mm gauge, 1:76 scale and DCC controlled using NCE Powercabs with sound on most locomotives, point control being by DCC controlled Tortoise motors and MERG driven servos. Buildings are either scratchbuilt or modified and detailed models from Petite Properties, and Spratt & Winkle delayed action couplings are used with concealed magnets for operation.";
    }
}
